 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    def bands(n, get_line):
        out = []
        i = 0
        while i < n:
            if any(get_line(i)):
                j = i
                while j + 1 < n and any(get_line(j + 1)):
                    j += 1
                if j - i + 1 >= 3:
                    out.append((i, j))
                i = j + 1
            else:
                i += 1
        return out

    rb = bands(h, lambda r: grid[r])
    cb = bands(w, lambda c: [grid[r][c] for r in range(h)])
    if not rb or not cb:
        return [row[:] for row in grid]
    rcent = [(a + b) // 2 for a, b in rb]
    ccent = [(a + b) // 2 for a, b in cb]
    colors = [[grid[r][c] for c in ccent] for r in rcent]
    from collections import Counter
    counts = Counter(v for row in colors for v in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for color in counts:
        if color == background:
            continue
        pts = [(i, j) for i, row in enumerate(colors) for j, v in enumerate(row) if v == color]
        if len(pts) < 2:
            continue
        minr, maxr = min(i for i, j in pts), max(i for i, j in pts)
        minc, maxc = min(j for i, j in pts), max(j for i, j in pts)
        corners = {(minr, minc), (minr, maxc), (maxr, minc), (maxr, maxc)}
        if len(pts) != 4 or set(pts) != corners or minr == maxr or minc == maxc:
            continue
        for rr in (minr, maxr):
            for j in range(minc, maxc):
                left, right = ccent[j], ccent[j + 1]
                for c in range(left + 1, right):
                    out[rcent[rr]][c] = color
        for cc in (minc, maxc):
            for i in range(minr, maxr):
                top, bottom = rcent[i], rcent[i + 1]
                for r in range(top + 1, bottom):
                    out[r][ccent[cc]] = color
    return out
