 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    base = Counter(v for row in grid for v in row if v != 0).most_common(1)[0][0]
    seen = set()
    components = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, base) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            cr = round(sum(y for y,x in cells) / len(cells))
            cc = round(sum(x for y,x in cells) / len(cells))
            components.setdefault(color, []).append((cr, cc))
    for color, pts in components.items():
        # Connect aligned markers in each row/column; extend only through blank cells.
        rows = {}
        cols = {}
        for r, c in pts:
            rows.setdefault(r, []).append(c)
            cols.setdefault(c, []).append(r)
        for r, cs in rows.items():
            cs.sort()
            for a, b in zip(cs, cs[1:]):
                for c in range(a + 1, b):
                    if out[r][c] == 0:
                        out[r][c] = color
        for c, rs in cols.items():
            rs.sort()
            for a, b in zip(rs, rs[1:]):
                for r in range(a + 1, b):
                    if out[r][c] == 0:
                        out[r][c] = color
    return out
