 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Identify the repeated tile lattice from the dominant nonzero frame color.
    counts = Counter(v for row in grid for v in row if v != 0)
    frame = counts.most_common(1)[0][0]
    # All cells not background/frame form marker components, one per tile.
    seen = set()
    markers = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, frame) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            # Mark the full rectangular component's center cell.
            rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
            markers.setdefault(color, []).append(((min(rs)+max(rs))//2, (min(cs)+max(cs))//2))
    out = [row[:] for row in grid]
    for color, pts in markers.items():
        rows, cols = {}, {}
        for r, c in pts:
            rows.setdefault(r, []).append(c)
            cols.setdefault(c, []).append(r)
        for r, cs in rows.items():
            cs.sort()
            if len(cs) >= 2:
                for c in range(cs[0]+1, cs[-1]):
                    if out[r][c] == 0: out[r][c] = color
        for c, rs in cols.items():
            rs.sort()
            if len(rs) >= 2:
                for r in range(rs[0]+1, rs[-1]):
                    if out[r][c] == 0: out[r][c] = color
    return out
