def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # The thin frame forms regularly spaced tile boundaries. Locate centers of each tile's interior.
    rs=[]; cs=[]
    for r in range(h):
        if any(grid[r][c] == frame for c in range(w)) and any(v not in (0,frame) for v in grid[r]):
            rs.append(r)
    for c in range(w):
        if any(grid[r][c] == frame for r in range(h)) and any(grid[r][c] not in (0,frame) for r in range(h)):
            cs.append(c)
    # Most marker blocks are components of same color. Centers are extracted via flood fill.
    seen=set(); marks={}
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color in (0,frame) or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]
        while q:
          y,x=q.popleft(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx));q.append((yy,xx))
        # For a rectangular solid marker the center is integer midpoint.
        rr=sorted(y for y,x in cells); cc=sorted(x for y,x in cells)
        marks.setdefault(color,[]).append(((rr[0]+rr[-1])//2,(cc[0]+cc[-1])//2))
    out=[row[:] for row in grid]
    for color,pts in marks.items():
      byrow={};bycol={}
      for r,c in pts: byrow.setdefault(r,[]).append(c);bycol.setdefault(c,[]).append(r)
      for r,values in byrow.items():
        if len(values)>1:
          for c in range(min(values)+1,max(values)):
            if out[r][c]==0: out[r][c]=color
      for c,values in bycol.items():
        if len(values)>1:
          for r in range(min(values)+1,max(values)):
            if out[r][c]==0: out[r][c]=color
    return out
