def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # Marker color is determined by each object, and matching markers draw connectors
    # on intervening blank bands in both aligned directions.
    seen=set(); marks={}
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color in (0,frame) or (r,c) in seen: continue
        q=deque([(r,c)]);seen.add((r,c));cells=[]
        while q:
          y,x=q.popleft();cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color: seen.add((yy,xx));q.append((yy,xx))
        ys=[y for y,x in cells];xs=[x for y,x in cells]
        marks.setdefault(color,[]).append(((min(ys)+max(ys))//2,(min(xs)+max(xs))//2))
    out=[row[:] for row in grid]
    for color,pts in marks.items():
      for r,c in pts:
        # Continue each marker along all four cardinal rays across empty space,
        # stopping at the next frame or non-background cell. Only rays ending at
        # another same-color marker are retained.
        for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
          y,x=r+dr,c+dc; path=[]
          while 0<=y<h and 0<=x<w and grid[y][x]==0:
            path.append((y,x)); y+=dr; x+=dc
          if 0<=y<h and 0<=x<w and grid[y][x]==color:
            for yy,xx in path: out[yy][xx]=color
    return out
