def transform(grid):
    h,w=len(grid),len(grid[0])
    frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # Find the repeated grid of cells from horizontal and vertical frame separators.
    def runs(indices):
        out=[]
        for i in indices:
            if out and i==out[-1][-1]+1: out[-1].append(i)
            else: out.append([i])
        return [x for x in out if len(x)>=3]
    rowruns=runs([r for r in range(h) if any(v==frame for v in grid[r]) and any(v not in (0,frame) for v in grid[r])])
    colruns=runs([c for c in range(w) if any(grid[r][c]==frame for r in range(h)) and any(grid[r][c] not in (0,frame) for r in range(h))])
    rcent=[x[len(x)//2] for x in rowruns]; ccent=[x[len(x)//2] for x in colruns]
    colors=[[grid[r][c] for c in ccent] for r in rcent]
    freq=Counter(v for row in colors for v in row)
    common=freq.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for color,n in freq.items():
        if color==common: continue
        pts=[(i,j) for i,row in enumerate(colors) for j,v in enumerate(row) if v==color]
        # Connect equal special cells across intervening tile gaps horizontally and vertically.
        for i,j in pts:
            for di,dj in ((0,1),(1,0)):
                k=1
                while i+di*k<len(colors) and j+dj*k<len(colors[0]) and colors[i+di*k][j+dj*k]==color:
                    k+=1
                if k>1:
                    for step in range(k-1):
                        y1,y2=rcent[i+di*step],rcent[i+di*(step+1)]
                        x1,x2=ccent[j+dj*step],ccent[j+dj*(step+1)]
                        if di==0:
                            for x in range(min(x1,x2)+1,max(x1,x2)):
                                if out[y1][x]==0: out[y1][x]=color
                        else:
                            for y in range(min(y1,y2)+1,max(y1,y2)):
                                if out[y][x1]==0: out[y][x1]=color
    return out
