          if (c1,c2)==(d1,d2) and (r2<s1 or s2<r1):
            top,bottom=(a,b) if r2<s1 else (b,a)
            for c in range(c1,c2+1):
              for r in range(top[1]+1,bottom[0]):
                if out[r][c]==0:out[r][c]=color
    return out
