    rows=[x[len(x)//2] for x in rr];cols=[x[len(x)//2] for x in cc]
    colors=[[grid[r][c] for c in cols] for r in rows]
    freq=Counter(v for line in colors for v in line);base=freq.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for color in freq:
      if color==base:continue
      for i in range(len(rows)):
        js=[j for j in range(len(cols)) if colors[i][j]==color]
        for a,b in zip(js,js[1:]):
          for c in range(cols[a]+1,cols[b]):
