def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    def runs(vals):
        groups=[]
        for x in vals:
            if groups and x==groups[-1][-1]+1:groups[-1].append(x)
            else:groups.append([x])
        return [g for g in groups if len(g)>=3]
    rg=runs([r for r in range(h) if frame in grid[r] and any(x not in (0,frame) for x in grid[r])])
    cg=runs([c for c in range(w) if any(grid[r][c]==frame for r in range(h)) and any(grid[r][c] not in (0,frame) for r in range(h))])
    rows=[g[len(g)//2] for g in rg]; cols=[g[len(g)//2] for g in cg]
    colors=[[grid[r][c] for c in cols] for r in rows]
    base=Counter(v for row in colors for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    for i in range(len(rows)):
        for j in range(len(cols)):
            color=colors[i][j]
            if color==base: continue
            # A special cell marks the crossing of a horizontal and vertical line.
            if any(colors[i][jj]==color for jj in range(len(cols)) if jj!=j):
                for c in range(1,w-1):
                    if out[rows[i]][c]==0:out[rows[i]][c]=color
            if any(colors[ii][j]==color for ii in range(len(rows)) if ii!=i):
                for r in range(1,h-1):
                    if out[r][cols[j]]==0:out[r][cols[j]]=color
    return out
