def transform(grid):
    h,w=len(grid),len(grid[0])
    freq=Counter(v for row in grid for v in row if v)
    border=freq.most_common(1)[0][0]
    # Locate tile interiors using the periodic border-and-gap structure.
    def runs(xs):
        groups=[]
        for x in xs:
            if groups and x==groups[-1][-1]+1:groups[-1].append(x)
            else:groups.append([x])
        return [g for g in groups if len(g)>=3]
    rr=runs([r for r in range(h) if border in grid[r] and any(v not in (0,border) for v in grid[r])])
    cc=runs([c for c in range(w) if any(grid[r][c]==border for r in range(h)) and any(grid[r][c] not in (0,border) for r in range(h))])
    rows=[g[len(g)//2] for g in rr]
    cols=[g[len(g)//2] for g in cc]
    centers=[[grid[r][c] for c in cols] for r in rows]
    # For each tile-cell position, if its color forms a 2x2 rectangular group,
    # connect adjacent cells of that color across the intervening blank strips.
    out=[row[:] for row in grid]
    nr,nc=len(rows),len(cols)
    for color in set(v for row in centers for v in row if v not in (0,border)):
        pts={(i,j) for i in range(nr) for j in range(nc) if centers[i][j]==color}
        if not pts: continue
        rmin,rmax=min(i for i,j in pts),max(i for i,j in pts)
        cmin,cmax=min(j for i,j in pts),max(j for i,j in pts)
        if len(pts)!=(rmax-rmin+1)*(cmax-cmin+1): continue
        # Draw horizontal bridges across each cell-to-cell gap, matching the colored tile band.
        for i in range(rmin,rmax+1):
            for j in range(cmin,cmax):
                r=rows[i]
                for c in range(cols[j]+1,cols[j+1]):
                    if out[r][c]==0: out[r][c]=color
        # Draw vertical bridges across each cell-to-cell gap.
        for j in range(cmin,cmax+1):
            c=cols[j]
            for i in range(rmin,rmax):
                for r in range(rows[i]+1,rows[i+1]):
                    if out[r][c]==0: out[r][c]=color
    return out
