def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    def runs(vals):
        groups=[]
        for x in vals:
            if groups and x==groups[-1][-1]+1:groups[-1].append(x)
            else:groups.append([x])
        return [g for g in groups if len(g)>=3]
    rg=runs([r for r in range(h) if frame in grid[r] and any(v not in (0,frame) for v in grid[r])])
    cg=runs([c for c in range(w) if any(grid[r][c]==frame for r in range(h)) and any(grid[r][c] not in (0,frame) for r in range(h))])
    rows=[g[len(g)//2] for g in rg]; cols=[g[len(g)//2] for g in cg]
    vals=[[grid[r][c] for c in cols] for r in rows]
    base=Counter(v for row in vals for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    # The exception color patches are replicated into adjacent same-position tiles.
    for i in range(len(rows)):
      for j in range(len(cols)):
        color=vals[i][j]
        if color==base:continue
        for k in range(j+1,len(cols)):
          if vals[i][k]==base:
            for c in range(cols[j]+1,cols[k]):
              if out[rows[i]][c]==0:out[rows[i]][c]=color
          elif vals[i][k]!=color:break
        for k in range(i+1,len(rows)):
          if vals[k][j]==base:
            for r in range(rows[i]+1,rows[k]):
              if out[r][cols[j]]==0:out[r][cols[j]]=color
          elif vals[k][j]!=color:break
    return out
