def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # Treat each separate color blob as a signal; connect equal signals sharing a row/column alignment.
    seen=set(); blobs={}
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color in (0,frame) or (r,c) in seen:continue
        q=deque([(r,c)]);seen.add((r,c));cells=[]
        while q:
          y,x=q.popleft();cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx));q.append((yy,xx))
        ys=[y for y,x in cells];xs=[x for y,x in cells]
        blobs.setdefault(color,[]).append((min(ys),max(ys),min(xs),max(xs)))
    out=[row[:] for row in grid]
    for color,boxes in blobs.items():
      # Lines connect only repeated components at the same tile-array coordinate (same center).
      for i,a in enumerate(boxes):
        r1,r2,c1,c2=a
        for b in boxes[i+1:]:
          s1,s2,d1,d2=b
          if (r1+r2)==(s1+s2) and (c2<d1 or d2<c1):
            left,right=(a,b) if c2<d1 else (b,a); r=(r1+r2)//2
            for c in range(left[3]+1,right[2]):
