def transform(grid):
    h,w=len(grid),len(grid[0]);frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # regular tiles have full rectangular borders; infer their bounding boxes as color runs
    def runs(xs):
      gs=[]
      for x in xs:
        if gs and x==gs[-1][-1]+1:gs[-1].append(x)
        else:gs.append([x])
      return [g for g in gs if len(g)>=4]
    rowgroups=runs([r for r in range(h) if frame in grid[r] and any(v not in(0,frame) for v in grid[r])])
    colgroups=runs([c for c in range(w) if any(grid[r][c]==frame for r in range(h)) and any(grid[r][c] not in(0,frame) for r in range(h))])
    # use central tile rows/columns to sample cells
    rows=[g[len(g)//2] for g in rowgroups];cols=[g[len(g)//2] for g in colgroups]
    a=[[grid[r][c] for c in cols] for r in rows]
    freq=Counter(v for row in a for v in row if v not in(0,frame))
    if not freq:return [row[:] for row in grid]
    base=freq.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for i in range(len(rows)):
      for j in range(len(cols)):
        color=a[i][j]
        if color in (0,frame,base):continue
        # repeated special-color cells are endpoints; bridge the aligned gaps
        for k in range(j+1,len(cols)):
          if a[i][k]==color:
            for c in range(cols[j]+1,cols[k]):
              if out[rows[i]][c]==0:out[rows[i]][c]=color
            break
        for k in range(i+1,len(rows)):
          if a[k][j]==color:
            for r in range(rows[i]+1,rows[k]):
              if out[r][cols[j]]==0:out[r][cols[j]]=color
            break
    return out
