def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # Grid tiles are 5x5 framed panels on a regular 7-cell pitch.
    # For each tile center, identify its interior signal color.
    centers=[]
    for r in range(2,h,7):
        line=[]
        for c in range(2,w,7):
            if r<h and c<w and grid[r][c] not in (0,frame): line.append(grid[r][c])
            else: line.append(0)
        centers.append(line)
    base=Counter(v for row in centers for v in row if v).most_common(1)[0][0]
    out=[row[:] for row in grid]
    nr,nc=len(centers),len(centers[0])
    # Find each marker (non-background), then extend it in rows/columns where
    # the same marker occurs, bridging only the intervening empty spaces.
    for i in range(nr):
      for j in range(nc):
        color=centers[i][j]
        if color in (0,base): continue
        for k in range(j+1,nc):
          if centers[i][k]==color:
            r=2+7*i
            for c in range(6+7*j,1+7*k):
              if 0<=c<w and out[r][c]==0:out[r][c]=color
            break
        for k in range(i+1,nr):
          if centers[k][j]==color:
            c=2+7*j
            for r in range(6+7*i,1+7*k):
              if 0<=r<h and out[r][c]==0:out[r][c]=color
            break
    return out
