        line.append(Counter(vals).most_common(1)[0][0] if vals else 0)
      a.append(line)
    counts=Counter(v for line in a for v in line if v)
    if not counts:return [row[:] for row in grid]
    base=counts.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for i in range(len(rows)):
      for j in range(len(cols)):
        color=a[i][j]
        if color in (0,base):continue
        # mark the gap between this exceptional cell and matching ones
        for k in range(j+1,len(cols)):
          if a[i][k]==color:
            y=rows[i]+2
            for x in range(cols[j]+4,cols[k]):
