def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]

    def bands(indices):
        groups = []
        for i in indices:
            if groups and i == groups[-1][-1] + 1:
                groups[-1].append(i)
            else:
                groups.append([i])
        return [g for g in groups if len(g) >= 3]

    row_bands = bands([r for r in range(h) if any(grid[r][c] != 0 for c in range(w))])
    col_bands = bands([c for c in range(w) if any(grid[r][c] != 0 for r in range(h))])
    rows = [g[len(g)//2] for g in row_bands]
    cols = [g[len(g)//2] for g in col_bands]
    if not rows or not cols:
        return [row[:] for row in grid]

    colors = [[grid[r][c] for c in cols] for r in rows]
    counts = Counter(v for line in colors for v in line if v not in (0, frame))
    if not counts:
        return [row[:] for row in grid]
    common = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Rare tile-center colors are linked across the blank gaps when they repeat
    # in the same tile row or column. Keep the connector one cell thick.
    for color in counts:
        if color == common:
            continue
        for i, r in enumerate(rows):
            js = [j for j in range(len(cols)) if colors[i][j] == color]
            for a, b in zip(js, js[1:]):
                for j in range(a, b):
                    for c in range(col_bands[j][-1] + 1, col_bands[j+1][0]):
                        if out[r][c] == 0:
                            out[r][c] = color
        for j, c in enumerate(cols):
            ins = [i for i in range(len(rows)) if colors[i][j] == color]
            for a, b in zip(ins, ins[1:]):
                for i in range(a, b):
                    for r in range(row_bands[i][-1] + 1, row_bands[i+1][0]):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
