def transform(grid):
    h, w = len(grid), len(grid[0])
    # Tile pattern has 5x5 cells with 2-cell gaps: each tile starts at 1 mod 7.
    starts_r = list(range(1, h, 7))
    starts_c = list(range(1, w, 7))
    # Frame is the most frequent color; each tile's signal is its interior modal color.
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    colors = []
    for sr in starts_r:
        row = []
        for sc in starts_c:
            vals = [grid[r][c] for r in range(sr+1, min(sr+4,h))
                    for c in range(sc+1, min(sc+4,w)) if grid[r][c] not in (0, frame)]
            row.append(Counter(vals).most_common(1)[0][0] if vals else 0)
        colors.append(row)
    counts = Counter(v for row in colors for v in row if v)
    base = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    nr, nc = len(starts_r), len(starts_c)
    # Connect all repeated non-base signals along their rows/columns, drawing only
    # in blank inter-tile gaps and never overwriting existing tile pixels.
    for color in counts:
        if color == base:
            continue
        for i in range(nr):
            js = [j for j in range(nc) if colors[i][j] == color]
            if len(js) >= 2:
                for a, b in zip(js, js[1:]):
                    rr = starts_r[i] + 2
                    for j in range(a, b):
                        for c in range(starts_c[j] + 5, starts_c[j+1]):
                            if out[rr][c] == 0:
                                out[rr][c] = color
        for j in range(nc):
            is_ = [i for i in range(nr) if colors[i][j] == color]
            if len(is_) >= 2:
                for a, b in zip(is_, is_[1:]):
                    cc = starts_c[j] + 2
                    for i in range(a, b):
                        for r in range(starts_r[i] + 5, starts_r[i+1]):
                            if out[r][cc] == 0:
                                out[r][cc] = color
    return out
