def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # Array cell centers are on 7-pixel periodic lattice, offset 2.
    rows=list(range(2,h,7)); cols=list(range(2,w,7))
    colors=[[grid[r][c] for c in cols] for r in rows]
    common=Counter(v for line in colors for v in line if v not in (0,frame)).most_common(1)[0][0]
    out=[row[:] for row in grid]
    # For every rare color, trace a full straight segment connecting its repeated occurrences.
    for color in set(v for line in colors for v in line if v not in(0,frame,common)):
      for i in range(len(rows)):
        js=[j for j in range(len(cols)) if colors[i][j]==color]
        if len(js)>=2:
          a,b=min(js),max(js)
          for c in range(cols[a]+1,cols[b]):
            if out[rows[i]][c]==0:out[rows[i]][c]=color
      for j in range(len(cols)):
        ins=[i for i in range(len(rows)) if colors[i][j]==color]
        if len(ins)>=2:
          a,b=min(ins),max(ins)
          for r in range(rows[a]+1,rows[b]):
            if out[r][cols[j]]==0:out[r][cols[j]]=color
    return out
