def transform(grid):
    h,w=len(grid),len(grid[0])
    freq=Counter(v for row in grid for v in row if v)
    frame=freq.most_common(1)[0][0]
    # Identify colored connected components other than the abundant tile interior color.
    vals=Counter(v for row in grid for v in row if v not in (0,frame))
    common=vals.most_common(1)[0][0]
    seen=set(); boxes={}
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color in (0,frame,common) or (r,c) in seen: continue
        q=deque([(r,c)]);seen.add((r,c)); cells=[]
        while q:
          y,x=q.popleft();cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx));q.append((yy,xx))
        ys=[y for y,x in cells];xs=[x for y,x in cells]
        boxes.setdefault(color,[]).append((min(ys),max(ys),min(xs),max(xs)))
    out=[row[:] for row in grid]
    for color,items in boxes.items():
      for a_idx,a in enumerate(items):
        r1,r2,c1,c2=a
        for b in items[a_idx+1:]:
          s1,s2,d1,d2=b
          # Join equal-sized pieces only when their center axes match.
          if (r1+r2)==(s1+s2) and (c2<d1 or d2<c1):
            left,right=(a,b) if c2<d1 else (b,a); y=(r1+r2)//2
            for x in range(left[3]+1,right[2]):
              if out[y][x]==0:out[y][x]=color
          if (c1+c2)==(d1+d2) and (r2<s1 or s2<r1):
            top,bottom=(a,b) if r2<s1 else (b,a); x=(c1+c2)//2
            for y in range(top[1]+1,bottom[0]):
              if out[y][x]==0:out[y][x]=color
    return out
