def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # Lattice tiles have regular 7x7 pitch, centers at offset 2.
    rows=list(range(2,h,7)); cols=list(range(2,w,7))
    colors=[[grid[r][c] for c in cols] for r in rows]
    counts=Counter(v for line in colors for v in line if v not in (0,frame))
    base=counts.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for color in counts:
      if color==base:continue
      # Match repeated signals only along the same lattice row or column.
      for i,r in enumerate(rows):
        js=[j for j in range(len(cols)) if colors[i][j]==color]
        for a,b in zip(js,js[1:]):
          # Draw the source's full vertical stripe width through gaps.
          for c in range(cols[a]-1,cols[a]+2):
            for x in range(c,cols[b]-1,7):
              if 0<=x<w and out[r][x]==0:out[r][x]=color
          for c in range(cols[a]+1,cols[b]):
            if out[r][c]==0:out[r][c]=color
      for j,c in enumerate(cols):
        ins=[i for i in range(len(rows)) if colors[i][j]==color]
        for a,b in zip(ins,ins[1:]):
          for r in range(rows[a]+1,rows[b]):
            if out[r][c]==0:out[r][c]=color
    return out
