def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # The connected framed panels are the repeated objects. Each panel interior
    # has a dominant fill and occasionally a smaller signal patch.
    tile_rows = list(range(1, h, 7))
    tile_cols = list(range(1, w, 7))
    signals = []
    for r0 in tile_rows:
        line=[]
        for c0 in tile_cols:
            vals=[grid[r][c] for r in range(r0+1,min(r0+4,h))
                  for c in range(c0+1,min(c0+4,w)) if grid[r][c] not in (0,frame)]
            line.append(Counter(vals).most_common(1)[0][0] if vals else 0)
        signals.append(line)
    freq=Counter(v for row in signals for v in row if v)
    base=freq.most_common(1)[0][0]
    out=[row[:] for row in grid]
    # For repeated exceptional signals, draw straight one-cell connectors
    # across intervening tile gaps, at the same position in the lattice.
    for color in freq:
        if color==base: continue
        for i in range(len(tile_rows)):
            js=[j for j in range(len(tile_cols)) if signals[i][j]==color]
            for a,b in zip(js,js[1:]):
                r=tile_rows[i]+2
                for c in range(tile_cols[a]+5,tile_cols[b]):
                    if out[r][c]==0: out[r][c]=color
        for j in range(len(tile_cols)):
            is_=[i for i in range(len(tile_rows)) if signals[i][j]==color]
            for a,b in zip(is_,is_[1:]):
                c=tile_cols[j]+2
                for r in range(tile_rows[a]+5,tile_rows[b]):
                    if out[r][c]==0: out[r][c]=color
    return out
