def transform(grid):
    h,w=len(grid),len(grid[0]); frame=Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # Find lattice tile rows/cols by bands of nonzero cells separated by blank gaps.
    def bands(coords):
        groups=[]
        for x in coords:
            if groups and x==groups[-1][-1]+1:groups[-1].append(x)
            else:groups.append([x])
        return [g for g in groups if len(g)>=3]
    rg=bands([r for r in range(h) if any(grid[r][c] for c in range(w))])
    cg=bands([c for c in range(w) if any(grid[r][c] for r in range(h))])
    # Interior tile center coordinates, excluding frame edges
    rows=[g[0]+2 for g in rg]; cols=[g[0]+2 for g in cg]
    centers=[[grid[r][c] for c in cols] for r in rows]
    freq=Counter(v for row in centers for v in row if v not in (0,frame))
    if not freq:return [row[:] for row in grid]
    common=freq.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for color in freq:
      if color==common:continue
      for i,r in enumerate(rows):
        js=[j for j in range(len(cols)) if centers[i][j]==color]
        for a,b in zip(js,js[1:]):
          for c in range(cols[a]+1,cols[b]):
            if out[r][c]==0:out[r][c]=color
      for j,c in enumerate(cols):
        ins=[i for i in range(len(rows)) if centers[i][j]==color]
        for a,b in zip(ins,ins[1:]):
          for r in range(rows[a]+1,rows[b]):
            if out[r][c]==0:out[r][c]=color
    return out
