def _bands(active):
    groups = []
    for x in active:
        if groups and x == groups[-1][-1] + 1:
            groups[-1].append(x)
        else:
            groups.append([x])
    return groups


def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]

    row_bands = [g for g in _bands([r for r in range(h) if any(grid[r][c] != 0 for c in range(w))]) if len(g) >= 3]
    col_bands = [g for g in _bands([c for c in range(w) if any(grid[r][c] != 0 for r in range(h))]) if len(g) >= 3]
    if not row_bands or not col_bands:
        return [row[:] for row in grid]

    tiles = []
    color_counts = Counter()
    for rb in row_bands:
        tile_row = []
        for cb in col_bands:
            vals = [grid[r][c] for r in rb for c in cb if grid[r][c] not in (0, frame)]
            color = Counter(vals).most_common(1)[0][0] if vals else 0
            tile_row.append(color)
            if color:
                color_counts[color] += 1
        tiles.append(tile_row)
    if not color_counts:
        return [row[:] for row in grid]
    base = color_counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Extend each non-dominant tile color across the blank gaps between its
    # outermost occurrences in a shared tile row or column.
    for color in color_counts:
        if color == base:
            continue
        for i, rb in enumerate(row_bands):
            js = [j for j, v in enumerate(tiles[i]) if v == color]
            if len(js) >= 2:
                first, last = js[0], js[-1]
                for j in range(first, last):
                    for r in rb[1:-1]:
                        for c in range(col_bands[j][-1] + 1, col_bands[j + 1][0]):
                            if out[r][c] == 0:
                                out[r][c] = color
        for j, cb in enumerate(col_bands):
            is_ = [i for i in range(len(row_bands)) if tiles[i][j] == color]
            if len(is_) >= 2:
                first, last = is_[0], is_[-1]
                for i in range(first, last):
                    for c in cb[1:-1]:
                        for r in range(row_bands[i][-1] + 1, row_bands[i + 1][0]):
                            if out[r][c] == 0:
                                out[r][c] = color
    return out
