def transform(grid):
    h, w = len(grid), len(grid[0])
    # The framed panels repeat every seven cells; their centers are at offset 3.
    centers_r = list(range(3, h, 7))
    centers_c = list(range(3, w, 7))
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    panel_colors = [[grid[r][c] for c in centers_c] for r in centers_r]
    counts = Counter(v for row in panel_colors if v not in (0, frame) for v in row if v not in (0, frame))
    if not counts:
        return [row[:] for row in grid]
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Rare panel colors act as signals: connect repeated signals in a common
    # panel row or column. Existing panel/frame cells stay untouched, so only
    # the blank gaps are painted.
    for color in counts:
        if color == background:
            continue
        for i, r in enumerate(centers_r):
            js = [j for j, value in enumerate(panel_colors[i]) if value == color]
            if len(js) >= 2:
                for c in range(centers_c[js[0]], centers_c[js[-1]] + 1):
                    if out[r][c] == 0:
                        out[r][c] = color
        for j, c in enumerate(centers_c):
            is_ = [i for i in range(len(centers_r)) if panel_colors[i][j] == color]
            if len(is_) >= 2:
                for r in range(centers_r[is_[0]], centers_r[is_[-1]] + 1):
                    if out[r][c] == 0:
                        out[r][c] = color
    return out
