def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # Discover the repeated tile pitch from the frame's one-cell bands.
    rstarts = [r for r in range(h) if grid[r][1] == frame and grid[r][2] == frame]
    cstarts = [c for c in range(w) if grid[1][c] == frame and grid[2][c] == frame]
    # Select the starts of each framed tile by their regular spacing.
    rstarts = [r for r in rstarts if r == 0 or r - rstarts[max(0, rstarts.index(r)-1)] > 1] if False else rstarts
    pitch_r = 7 if len(rstarts) > 1 else h
    pitch_c = 7 if len(cstarts) > 1 else w
    tr = list(range(1, h, pitch_r))
    tc = list(range(1, w, pitch_c))
    # Modal interior color is the ordinary tile fill; other colors are signals.
    tile = []
    counts = Counter()
    for r0 in tr:
        row = []
        for c0 in tc:
            vals = [grid[r][c] for r in range(r0+1, min(r0+4,h))
                    for c in range(c0+1, min(c0+4,w)) if grid[r][c] not in (0, frame)]
            color = Counter(vals).most_common(1)[0][0] if vals else 0
            row.append(color)
            if color: counts[color] += 1
        tile.append(row)
    if not counts:
        return [row[:] for row in grid]
    base = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Connect repeated exceptional tile patterns, filling only the blank gaps
    # and copying their full 3x3 interior footprint.
    for color in counts:
        if color == base:
            continue
        for i, r0 in enumerate(tr):
            js = [j for j, v in enumerate(tile[i]) if v == color]
            for a, b in zip(js, js[1:]):
                for r in range(r0+1, min(r0+4,h)):
                    for k in range(a, b):
                        for c in range(tc[k]+4, tc[k+1]):
                            if out[r][c] == 0:
                                out[r][c] = color
        for j, c0 in enumerate(tc):
            ii = [i for i in range(len(tr)) if tile[i][j] == color]
            for a, b in zip(ii, ii[1:]):
                for c in range(c0+1, min(c0+4,w)):
                    for k in range(a, b):
                        for r in range(tr[k]+4, tr[k+1]):
                            if out[r][c] == 0:
                                out[r][c] = color
    return out
