def _bands(indices):
    groups = []
    for x in indices:
        if groups and x == groups[-1][-1] + 1:
            groups[-1].append(x)
        else:
            groups.append([x])
    return groups


def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    row_bands = _bands([r for r in range(h) if any(grid[r][c] != 0 for c in range(w))])
    col_bands = _bands([c for c in range(w) if any(grid[r][c] != 0 for r in range(h))])

    # Each nonzero band is a framed tile. Sample its interior color.
    tiles = []
    color_counts = Counter()
    for rb in row_bands:
        tile_row = []
        for cb in col_bands:
            vals = [grid[r][c] for r in rb[1:-1] for c in cb[1:-1]
                    if grid[r][c] not in (0, frame)]
            color = Counter(vals).most_common(1)[0][0] if vals else 0
            tile_row.append(color)
            if color:
                color_counts[color] += 1
        tiles.append(tile_row)

    if not color_counts:
        return [row[:] for row in grid]
    base = color_counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # The most common tile color is the regular background. Repeated non-background
    # tile colors extend through the empty gaps between aligned matching tiles.
    for color in color_counts:
        if color == base:
            continue
        for i, rb in enumerate(row_bands):
            js = [j for j, value in enumerate(tiles[i]) if value == color]
            for a, b in zip(js, js[1:]):
                for r in rb[1:-1]:
                    for c in range(col_bands[a][-1] + 1, col_bands[b][0]):
                        if out[r][c] == 0:
                            out[r][c] = color
        for j, cb in enumerate(col_bands):
            is_ = [i for i in range(len(row_bands)) if tiles[i][j] == color]
            for a, b in zip(is_, is_[1:]):
                for c in cb[1:-1]:
                    for r in range(row_bands[a][-1] + 1, row_bands[b][0]):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
