def _bands(indices):
    groups = []
    for x in indices:
        if groups and x == groups[-1][-1] + 1:
            groups[-1].append(x)
        else:
            groups.append([x])
    return [g for g in groups if len(g) >= 3]


def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    row_bands = _bands([r for r in range(h) if any(grid[r][c] != 0 for c in range(w))])
    col_bands = _bands([c for c in range(w) if any(grid[r][c] != 0 for r in range(h))])
    if not row_bands or not col_bands:
        return [row[:] for row in grid]

    # A panel's signal is its most common non-frame interior color.
    panels = []
    counts = Counter()
    for rb in row_bands:
        row = []
        for cb in col_bands:
            vals = [grid[r][c] for r in rb[1:-1] for c in cb[1:-1]
                    if grid[r][c] not in (0, frame)]
            color = Counter(vals).most_common(1)[0][0] if vals else 0
            row.append(color)
            if color:
                counts[color] += 1
        panels.append(row)
    if not counts:
        return [row[:] for row in grid]
    base = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Repeated non-background panel signals are joined by a one-cell line
    # through the centers of intervening gaps (horizontal and vertical).
    for color in counts:
        if color == base:
            continue
        for i, rb in enumerate(row_bands):
            js = [j for j, v in enumerate(panels[i]) if v == color]
            for a, b in zip(js, js[1:]):
                r = rb[len(rb) // 2]
                for j in range(a, b):
                    for c in range(col_bands[j][-1] + 1, col_bands[j + 1][0]):
                        if out[r][c] == 0:
                            out[r][c] = color
        for j, cb in enumerate(col_bands):
            is_ = [i for i in range(len(row_bands)) if panels[i][j] == color]
            for a, b in zip(is_, is_[1:]):
                c = cb[len(cb) // 2]
                for i in range(a, b):
                    for r in range(row_bands[i][-1] + 1, row_bands[i + 1][0]):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
